 public static BitmapSource RenderBoardSize(BoardItem[] items,Rect bounds,int width,int height,bool oled){if(width<1||height<1||(long)width*height>64_000_000)throw new IOException("Export must be within 64 million pixels.");var visual=new DrawingVisual();using(var dc=visual.RenderOpen()){dc.DrawRectangle(new SolidColorBrush(oled?Colors.Black:Ui.CanvasColor),null,new Rect(0,0,width,height));foreach(var item in items){var r=new Rect((item.Rect.X-bounds.X)*width/bounds.Width,(item.Rect.Y-bounds.Y)*height/bounds.Height,item.Rect.Width*width/bounds.Width,item.Rect.Height*height/bounds.Height);var image=item.Edited?item.Image:ImageCache.Read(item.Path,(int)Math.Ceiling(Math.Max(r.Width,r.Height)));dc.DrawImage(image,r);}}var result=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);result.Render(visual);result.Freeze();return result;}
