 static string FileSizeText(long bytes)=>bytes>=1048576?$"{bytes/1048576d:0.##} MB":$"{bytes/1024d:0.##} KB";
 static byte[] EncodeImage(BitmapSource image,bool png,int quality){BitmapEncoder enc=png?new PngBitmapEncoder():new JpegBitmapEncoder{QualityLevel=quality};enc.Frames.Add(BitmapFrame.Create(image));using var stream=new MemoryStream();enc.Save(stream);return stream.ToArray();}
