  var error=Ui.Label("",11);error.TextWrapping=TextWrapping.Wrap;p.Children.Add(error);string? destination=null;bool overwrite=false;int ow=0,oh=0,q=95;bool Values(){return int.TryParse(width.Text,out ow)&&int.TryParse(height.Text,out oh)&&int.TryParse(quality.Text,out q)&&ow>0&&oh>0&&(long)ow*oh<=100_000_000&&q>=1&&q<=100;}
