 static Grid DimensionFields(TextBox height,TextBox width,string heightLabel,string widthLabel){var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition());grid.RowDefinitions.Add(new RowDefinition());grid.RowDefinitions.Add(new RowDefinition());var h=Ui.Label(heightLabel,12);var w=Ui.Label(widthLabel,12);Grid.SetColumn(w,1);grid.Children.Add(h);grid.Children.Add(w);Grid.SetRow(height,1);Grid.SetRow(width,1);Grid.SetColumn(width,1);grid.Children.Add(height);grid.Children.Add(width);return grid;}
